import json
from pathlib import Path
for path in [Path('/app/data/load_data.ipynb'), Path('/app/code/notebooks/demo_t2p_ouputs.ipynb')]:
    print(f'===== {path} =====')
    nb=json.loads(path.read_text())
    for i,cell in enumerate(nb['cells']):
        if cell.get('cell_type')!='code':
            continue
        src=''.join(cell.get('source', []))
        if any(k in src for k in ['motion', 'tstamps', 'interframe', 'iscell', 'Fneu', 'spks', 'dff', 'bin', 'rolling', 'resample']):
            print(f'--- cell {i} ---')
            print(src[:3000])
            print()
